/* Offscreen Vulkan test for the emulated V3D (Mesa v3dv), compared against lavapipe.
 *
 *   vktest run DEVICE-SUBSTRING DIR    render the scenes into DIR/vk_<scene>.rgba (128x128 RGBA8)
 *
 * Scenes: depth-tested coloured triangles; a texture uploaded through a staging buffer with its
 * mipmaps generated by vkCmdBlitImage, sampled trilinearly with alpha blending; a compute
 * shader with shared memory and a barrier (checked exactly). Shaders: *.spv next to the binary
 * (glslangValidator -V). Built in the guest: gcc -O1 -o vktest vktest.c -lvulkan
 */
#include <vulkan/vulkan.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define W 128
#define H 128
#define CK(x) do { VkResult r_ = (x); if (r_ != VK_SUCCESS) { fprintf(stderr, "%s:%d: %s = %d\n", __FILE__, __LINE__, #x, r_); exit(1); } } while (0)

static VkInstance inst;
static VkPhysicalDevice pd;
static VkDevice dev;
static VkQueue q;
static uint32_t qf;
static VkCommandPool pool;
static VkPhysicalDeviceMemoryProperties mp;

static uint32_t memtype(uint32_t bits, VkMemoryPropertyFlags f) {
    for (uint32_t i = 0; i < mp.memoryTypeCount; i++)
        if ((bits & (1u << i)) && (mp.memoryTypes[i].propertyFlags & f) == f) return i;
    fprintf(stderr, "no memory type\n"); exit(1);
}

static VkDeviceMemory alloc(VkMemoryRequirements r, VkMemoryPropertyFlags f) {
    VkMemoryAllocateInfo ai = {VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO, NULL, r.size, memtype(r.memoryTypeBits, f)};
    VkDeviceMemory m; CK(vkAllocateMemory(dev, &ai, NULL, &m)); return m;
}

static VkBuffer buffer(VkDeviceSize size, VkBufferUsageFlags u, VkDeviceMemory *mem, void **map) {
    VkBufferCreateInfo bi = {VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO, NULL, 0, size, u, VK_SHARING_MODE_EXCLUSIVE, 0, NULL};
    VkBuffer b; CK(vkCreateBuffer(dev, &bi, NULL, &b));
    VkMemoryRequirements r; vkGetBufferMemoryRequirements(dev, b, &r);
    *mem = alloc(r, VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);
    CK(vkBindBufferMemory(dev, b, *mem, 0));
    CK(vkMapMemory(dev, *mem, 0, size, 0, map));
    return b;
}

static VkImage image(VkFormat f, uint32_t w, uint32_t h, uint32_t levels, VkImageUsageFlags u, VkImageView *view, VkImageAspectFlags aspect) {
    VkImageCreateInfo ii = {VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO, NULL, 0, VK_IMAGE_TYPE_2D, f, {w, h, 1}, levels, 1, VK_SAMPLE_COUNT_1_BIT,
                            VK_IMAGE_TILING_OPTIMAL, u, VK_SHARING_MODE_EXCLUSIVE, 0, NULL, VK_IMAGE_LAYOUT_UNDEFINED};
    VkImage im; CK(vkCreateImage(dev, &ii, NULL, &im));
    VkMemoryRequirements r; vkGetImageMemoryRequirements(dev, im, &r);
    CK(vkBindImageMemory(dev, im, alloc(r, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT), 0));
    VkImageViewCreateInfo vi = {VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO, NULL, 0, im, VK_IMAGE_VIEW_TYPE_2D, f, {0}, {aspect, 0, levels, 0, 1}};
    CK(vkCreateImageView(dev, &vi, NULL, view));
    return im;
}

static VkShaderModule shader(const char *path) {
    FILE *f = fopen(path, "rb"); if (!f) { fprintf(stderr, "no %s\n", path); exit(1); }
    static uint32_t code[65536]; size_t n = fread(code, 1, sizeof code, f); fclose(f);
    VkShaderModuleCreateInfo ci = {VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO, NULL, 0, n, code};
    VkShaderModule m; CK(vkCreateShaderModule(dev, &ci, NULL, &m)); return m;
}

static VkCommandBuffer begin(void) {
    VkCommandBufferAllocateInfo ai = {VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO, NULL, pool, VK_COMMAND_BUFFER_LEVEL_PRIMARY, 1};
    VkCommandBuffer cb; CK(vkAllocateCommandBuffers(dev, &ai, &cb));
    VkCommandBufferBeginInfo bi = {VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO, NULL, VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT, NULL};
    CK(vkBeginCommandBuffer(cb, &bi));
    return cb;
}

static void submit(VkCommandBuffer cb) {
    CK(vkEndCommandBuffer(cb));
    VkSubmitInfo si = {VK_STRUCTURE_TYPE_SUBMIT_INFO, NULL, 0, NULL, NULL, 1, &cb, 0, NULL};
    CK(vkQueueSubmit(q, 1, &si, VK_NULL_HANDLE));
    CK(vkQueueWaitIdle(q));
}

static void barrier(VkCommandBuffer cb, VkImage im, VkImageAspectFlags aspect, uint32_t level, uint32_t nlevels, VkImageLayout from, VkImageLayout to) {
    VkImageMemoryBarrier b = {VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER, NULL, VK_ACCESS_MEMORY_WRITE_BIT, VK_ACCESS_MEMORY_READ_BIT | VK_ACCESS_MEMORY_WRITE_BIT,
                              from, to, VK_QUEUE_FAMILY_IGNORED, VK_QUEUE_FAMILY_IGNORED, im, {aspect, level, nlevels, 0, 1}};
    vkCmdPipelineBarrier(cb, VK_PIPELINE_STAGE_ALL_COMMANDS_BIT, VK_PIPELINE_STAGE_ALL_COMMANDS_BIT, 0, 0, NULL, 0, NULL, 1, &b);
}

static void save(VkImage im, const char *path) {
    VkDeviceMemory m; void *p;
    VkBuffer b = buffer(W * H * 4, VK_BUFFER_USAGE_TRANSFER_DST_BIT, &m, &p);
    VkCommandBuffer cb = begin();
    barrier(cb, im, VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL);
    VkBufferImageCopy c = {0, 0, 0, {VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1}, {0, 0, 0}, {W, H, 1}};
    vkCmdCopyImageToBuffer(cb, im, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL, b, 1, &c);
    submit(cb);
    /* flip to bottom-up rows like glReadPixels, so gltest's comparison applies */
    FILE *f = fopen(path, "wb");
    for (int y = H - 1; y >= 0; y--) fwrite((char *)p + y * W * 4, 1, W * 4, f);
    fclose(f);
}

int main(int argc, char **argv) {
    if (argc < 4 || strcmp(argv[1], "run")) { fprintf(stderr, "usage: vktest run DEVICE DIR\n"); return 2; }
    const char *want = argv[2], *dir = argv[3];
    VkApplicationInfo app = {VK_STRUCTURE_TYPE_APPLICATION_INFO, NULL, "vktest", 1, NULL, 0, VK_API_VERSION_1_1};
    VkInstanceCreateInfo ici = {VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO, NULL, 0, &app, 0, NULL, 0, NULL};
    CK(vkCreateInstance(&ici, NULL, &inst));
    uint32_t n = 8; VkPhysicalDevice pds[8]; CK(vkEnumeratePhysicalDevices(inst, &n, pds));
    for (uint32_t i = 0; i < n; i++) {
        VkPhysicalDeviceProperties pp; vkGetPhysicalDeviceProperties(pds[i], &pp);
        if (strstr(pp.deviceName, want)) { pd = pds[i]; printf("device: %s\n", pp.deviceName); }
    }
    if (!pd) { fprintf(stderr, "no device matching %s\n", want); return 1; }
    vkGetPhysicalDeviceMemoryProperties(pd, &mp);
    float prio = 1;
    VkDeviceQueueCreateInfo qci = {VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO, NULL, 0, 0, 1, &prio};
    qf = 0;
    VkDeviceCreateInfo dci = {VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO, NULL, 0, 1, &qci, 0, NULL, 0, NULL, NULL};
    CK(vkCreateDevice(pd, &dci, NULL, &dev));
    vkGetDeviceQueue(dev, qf, 0, &q);
    VkCommandPoolCreateInfo pci = {VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO, NULL, 0, qf};
    CK(vkCreateCommandPool(dev, &pci, NULL, &pool));

    /* targets */
    VkImageView cview, dview, tview;
    VkImage cimg = image(VK_FORMAT_R8G8B8A8_UNORM, W, H, 1, VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT | VK_IMAGE_USAGE_TRANSFER_SRC_BIT, &cview, VK_IMAGE_ASPECT_COLOR_BIT);
    VkImage dimg = image(VK_FORMAT_D32_SFLOAT, W, H, 1, VK_IMAGE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT, &dview, VK_IMAGE_ASPECT_DEPTH_BIT);
    (void)dimg;

    /* a 64x64 texture with 7 levels: staging upload of level 0, blits for the rest */
    VkImage timg = image(VK_FORMAT_R8G8B8A8_UNORM, 64, 64, 7, VK_IMAGE_USAGE_SAMPLED_BIT | VK_IMAGE_USAGE_TRANSFER_DST_BIT | VK_IMAGE_USAGE_TRANSFER_SRC_BIT, &tview, VK_IMAGE_ASPECT_COLOR_BIT);
    {
        VkDeviceMemory m; unsigned char *p;
        VkBuffer b = buffer(64 * 64 * 4, VK_BUFFER_USAGE_TRANSFER_SRC_BIT, &m, (void **)&p);
        for (int y = 0; y < 64; y++) for (int x = 0; x < 64; x++) {
            unsigned char *t = p + (y * 64 + x) * 4;
            t[0] = x * 4; t[1] = y * 4; t[2] = ((x / 8 + y / 8) & 1) ? 255 : 0; t[3] = 160 + (x & 63);
        }
        VkCommandBuffer cb = begin();
        barrier(cb, timg, VK_IMAGE_ASPECT_COLOR_BIT, 0, 7, VK_IMAGE_LAYOUT_UNDEFINED, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL);
        VkBufferImageCopy c = {0, 0, 0, {VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1}, {0, 0, 0}, {64, 64, 1}};
        vkCmdCopyBufferToImage(cb, b, timg, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, 1, &c);
        for (uint32_t l = 1; l < 7; l++) {
            barrier(cb, timg, VK_IMAGE_ASPECT_COLOR_BIT, l - 1, 1, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL);
            int32_t s = 64 >> (l - 1), d = 64 >> l;
            VkImageBlit bl = {{VK_IMAGE_ASPECT_COLOR_BIT, l - 1, 0, 1}, {{0, 0, 0}, {s, s, 1}}, {VK_IMAGE_ASPECT_COLOR_BIT, l, 0, 1}, {{0, 0, 0}, {d, d, 1}}};
            vkCmdBlitImage(cb, timg, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL, timg, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, 1, &bl, VK_FILTER_LINEAR);
            barrier(cb, timg, VK_IMAGE_ASPECT_COLOR_BIT, l - 1, 1, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL);
        }
        barrier(cb, timg, VK_IMAGE_ASPECT_COLOR_BIT, 6, 1, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL);
        submit(cb);
    }
    VkSamplerCreateInfo sci = {VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO, NULL, 0, VK_FILTER_LINEAR, VK_FILTER_LINEAR, VK_SAMPLER_MIPMAP_MODE_LINEAR,
                               VK_SAMPLER_ADDRESS_MODE_REPEAT, VK_SAMPLER_ADDRESS_MODE_MIRRORED_REPEAT, VK_SAMPLER_ADDRESS_MODE_REPEAT, 0, VK_FALSE, 1,
                               VK_FALSE, VK_COMPARE_OP_ALWAYS, 0, 16, VK_BORDER_COLOR_FLOAT_OPAQUE_BLACK, VK_FALSE};
    VkSampler smp; CK(vkCreateSampler(dev, &sci, NULL, &smp));

    /* render pass + pipelines */
    VkAttachmentDescription at[2] = {
        {0, VK_FORMAT_R8G8B8A8_UNORM, VK_SAMPLE_COUNT_1_BIT, VK_ATTACHMENT_LOAD_OP_CLEAR, VK_ATTACHMENT_STORE_OP_STORE, VK_ATTACHMENT_LOAD_OP_DONT_CARE, VK_ATTACHMENT_STORE_OP_DONT_CARE, VK_IMAGE_LAYOUT_UNDEFINED, VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL},
        {0, VK_FORMAT_D32_SFLOAT, VK_SAMPLE_COUNT_1_BIT, VK_ATTACHMENT_LOAD_OP_CLEAR, VK_ATTACHMENT_STORE_OP_DONT_CARE, VK_ATTACHMENT_LOAD_OP_DONT_CARE, VK_ATTACHMENT_STORE_OP_DONT_CARE, VK_IMAGE_LAYOUT_UNDEFINED, VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL}};
    VkAttachmentReference cr = {0, VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL}, dr = {1, VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL};
    VkSubpassDescription sp = {0, VK_PIPELINE_BIND_POINT_GRAPHICS, 0, NULL, 1, &cr, NULL, &dr, 0, NULL};
    VkRenderPassCreateInfo rci = {VK_STRUCTURE_TYPE_RENDER_PASS_CREATE_INFO, NULL, 0, 2, at, 1, &sp, 0, NULL};
    VkRenderPass rp; CK(vkCreateRenderPass(dev, &rci, NULL, &rp));
    VkImageView views[2] = {cview, dview};
    VkFramebufferCreateInfo fci = {VK_STRUCTURE_TYPE_FRAMEBUFFER_CREATE_INFO, NULL, 0, rp, 2, views, W, H, 1};
    VkFramebuffer fb; CK(vkCreateFramebuffer(dev, &fci, NULL, &fb));

    VkDescriptorSetLayoutBinding lb = {0, VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER, 1, VK_SHADER_STAGE_FRAGMENT_BIT, NULL};
    VkDescriptorSetLayoutCreateInfo dlci = {VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO, NULL, 0, 1, &lb};
    VkDescriptorSetLayout dsl; CK(vkCreateDescriptorSetLayout(dev, &dlci, NULL, &dsl));
    VkPushConstantRange pcr = {VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, 0, 16};
    VkPipelineLayoutCreateInfo plci = {VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO, NULL, 0, 1, &dsl, 1, &pcr};
    VkPipelineLayout pl; CK(vkCreatePipelineLayout(dev, &plci, NULL, &pl));
    VkDescriptorPoolSize ps[2] = {{VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER, 1}, {VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, 1}};
    VkDescriptorPoolCreateInfo dpci = {VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO, NULL, 0, 2, 2, ps};
    VkDescriptorPool dp; CK(vkCreateDescriptorPool(dev, &dpci, NULL, &dp));
    VkDescriptorSetAllocateInfo dsai = {VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO, NULL, dp, 1, &dsl};
    VkDescriptorSet ds; CK(vkAllocateDescriptorSets(dev, &dsai, &ds));
    VkDescriptorImageInfo dii = {smp, tview, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL};
    VkWriteDescriptorSet wds = {VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET, NULL, ds, 0, 0, 1, VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER, &dii, NULL, NULL};
    vkUpdateDescriptorSets(dev, 1, &wds, 0, NULL);

    char path[512];
    VkPipeline pipes[2];
    for (int k = 0; k < 2; k++) {
        snprintf(path, sizeof path, "vk_%s.vert.spv", k ? "tex" : "col");
        VkShaderModule vs = shader(path);
        snprintf(path, sizeof path, "vk_%s.frag.spv", k ? "tex" : "col");
        VkShaderModule fs = shader(path);
        VkPipelineShaderStageCreateInfo st[2] = {{VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO, NULL, 0, VK_SHADER_STAGE_VERTEX_BIT, vs, "main", NULL},
                                                 {VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO, NULL, 0, VK_SHADER_STAGE_FRAGMENT_BIT, fs, "main", NULL}};
        VkVertexInputBindingDescription vb = {0, 8 * 4, VK_VERTEX_INPUT_RATE_VERTEX};
        VkVertexInputAttributeDescription va[2] = {{0, 0, VK_FORMAT_R32G32B32A32_SFLOAT, 0}, {1, 0, VK_FORMAT_R32G32B32A32_SFLOAT, 16}};
        VkPipelineVertexInputStateCreateInfo vi = {VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO, NULL, 0, 1, &vb, 2, va};
        VkPipelineInputAssemblyStateCreateInfo ia = {VK_STRUCTURE_TYPE_PIPELINE_INPUT_ASSEMBLY_STATE_CREATE_INFO, NULL, 0, VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST, VK_FALSE};
        VkViewport vp = {0, 0, W, H, 0, 1};
        VkRect2D sc = {{0, 0}, {W, H}};
        VkPipelineViewportStateCreateInfo vps = {VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO, NULL, 0, 1, &vp, 1, &sc};
        VkPipelineRasterizationStateCreateInfo rs = {VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO, NULL, 0, VK_FALSE, VK_FALSE, VK_POLYGON_MODE_FILL,
                                                     VK_CULL_MODE_NONE, VK_FRONT_FACE_COUNTER_CLOCKWISE, VK_FALSE, 0, 0, 0, 1};
        VkPipelineMultisampleStateCreateInfo ms = {VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO, NULL, 0, VK_SAMPLE_COUNT_1_BIT, VK_FALSE, 0, NULL, VK_FALSE, VK_FALSE};
        VkPipelineDepthStencilStateCreateInfo dss = {VK_STRUCTURE_TYPE_PIPELINE_DEPTH_STENCIL_STATE_CREATE_INFO, NULL, 0, VK_TRUE, VK_TRUE, VK_COMPARE_OP_LESS, VK_FALSE, VK_FALSE, {0}, {0}, 0, 1};
        VkPipelineColorBlendAttachmentState cba = {k ? VK_TRUE : VK_FALSE, VK_BLEND_FACTOR_SRC_ALPHA, VK_BLEND_FACTOR_ONE_MINUS_SRC_ALPHA, VK_BLEND_OP_ADD,
                                                   VK_BLEND_FACTOR_ONE, VK_BLEND_FACTOR_ZERO, VK_BLEND_OP_ADD, 0xf};
        VkPipelineColorBlendStateCreateInfo cb = {VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO, NULL, 0, VK_FALSE, VK_LOGIC_OP_COPY, 1, &cba, {0}};
        VkGraphicsPipelineCreateInfo gp = {VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO, NULL, 0, 2, st, &vi, &ia, NULL, &vps, &rs, &ms, &dss, &cb, NULL, pl, rp, 0, VK_NULL_HANDLE, 0};
        CK(vkCreateGraphicsPipelines(dev, VK_NULL_HANDLE, 1, &gp, NULL, &pipes[k]));
    }
    /* geometry: pos.xyzw, col/uv.xyzw */
    float verts[] = {
        -0.8f, 0.8f, 0.3f, 1, 1, 0, 0, 1,   0.6f, 0.8f, 0.3f, 1, 1, 1, 0, 1,   -0.1f, -0.7f, 0.3f, 1, 1, 0, 1, 1,
        -0.6f, 0.6f, 0.6f, 1, 0, 1, 0, 1,   0.9f, 0.4f, 0.1f, 1, 0, 1, 1, 1,    0.3f, -0.9f, 0.9f, 1, 0, 0, 1, 1,
        -0.9f, -0.9f, 0.05f, 1, 0, 0, 0, 0, 0.9f, -0.9f, 0.05f, 1, 3, 0, 0, 0,  -0.9f, 0.9f, 0.05f, 1, 0, 3, 0, 0,
         0.9f, -0.9f, 0.05f, 1, 3, 0, 0, 0, 0.9f, 0.9f, 0.05f, 1, 3, 3, 0, 0,  -0.9f, 0.9f, 0.05f, 1, 0, 3, 0, 0};
    VkDeviceMemory vm; void *vp_;
    VkBuffer vbuf = buffer(sizeof verts, VK_BUFFER_USAGE_VERTEX_BUFFER_BIT, &vm, &vp_);
    memcpy(vp_, verts, sizeof verts);

    for (int scene = 0; scene < 2; scene++) {
        VkCommandBuffer cb = begin();
        VkClearValue cv[2] = {{.color = {{0.1f, 0.2f, 0.3f, 1}}}, {.depthStencil = {1, 0}}};
        VkRenderPassBeginInfo rbi = {VK_STRUCTURE_TYPE_RENDER_PASS_BEGIN_INFO, NULL, rp, fb, {{0, 0}, {W, H}}, 2, cv};
        vkCmdBeginRenderPass(cb, &rbi, VK_SUBPASS_CONTENTS_INLINE);
        VkDeviceSize off = 0;
        vkCmdBindVertexBuffers(cb, 0, 1, &vbuf, &off);
        float pc[4] = {0.5f, 0.25f, 0, 0};
        if (scene == 0) {
            vkCmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_GRAPHICS, pipes[0]);
            vkCmdPushConstants(cb, pl, VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, 0, 16, pc);
            vkCmdDraw(cb, 6, 1, 0, 0);
        } else {
            vkCmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_GRAPHICS, pipes[0]);
            vkCmdPushConstants(cb, pl, VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, 0, 16, pc);
            vkCmdDraw(cb, 3, 1, 0, 0);
            vkCmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_GRAPHICS, pipes[1]);
            vkCmdBindDescriptorSets(cb, VK_PIPELINE_BIND_POINT_GRAPHICS, pl, 0, 1, &ds, 0, NULL);
            vkCmdPushConstants(cb, pl, VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, 0, 16, pc);
            vkCmdDraw(cb, 6, 1, 6, 0);
        }
        vkCmdEndRenderPass(cb);
        submit(cb);
        snprintf(path, sizeof path, "%s/vk_%s.rgba", dir, scene ? "texture_blend" : "depth_tris");
        save(cimg, path);
        printf("scene vk_%s done\n", scene ? "texture_blend" : "depth_tris");
    }

    /* compute */
    {
        VkDescriptorSetLayoutBinding cb0 = {0, VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, 1, VK_SHADER_STAGE_COMPUTE_BIT, NULL};
        VkDescriptorSetLayoutCreateInfo cl = {VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO, NULL, 0, 1, &cb0};
        VkDescriptorSetLayout cdsl; CK(vkCreateDescriptorSetLayout(dev, &cl, NULL, &cdsl));
        VkPipelineLayoutCreateInfo cpl = {VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO, NULL, 0, 1, &cdsl, 0, NULL};
        VkPipelineLayout cpli; CK(vkCreatePipelineLayout(dev, &cpl, NULL, &cpli));
        VkComputePipelineCreateInfo cp = {VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO, NULL, 0,
                                          {VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO, NULL, 0, VK_SHADER_STAGE_COMPUTE_BIT, shader("vk_comp.comp.spv"), "main", NULL}, cpli, VK_NULL_HANDLE, 0};
        VkPipeline cpipe; CK(vkCreateComputePipelines(dev, VK_NULL_HANDLE, 1, &cp, NULL, &cpipe));
        VkDeviceMemory bm; unsigned *bp;
        VkBuffer sb = buffer(1024 * 4, VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, &bm, (void **)&bp);
        memset(bp, 0, 1024 * 4);
        VkDescriptorSetAllocateInfo ca = {VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO, NULL, dp, 1, &cdsl};
        VkDescriptorSet cds; CK(vkAllocateDescriptorSets(dev, &ca, &cds));
        VkDescriptorBufferInfo dbi = {sb, 0, VK_WHOLE_SIZE};
        VkWriteDescriptorSet w = {VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET, NULL, cds, 0, 0, 1, VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, NULL, &dbi, NULL};
        vkUpdateDescriptorSets(dev, 1, &w, 0, NULL);
        VkCommandBuffer cb = begin();
        vkCmdBindPipeline(cb, VK_PIPELINE_BIND_POINT_COMPUTE, cpipe);
        vkCmdBindDescriptorSets(cb, VK_PIPELINE_BIND_POINT_COMPUTE, cpli, 0, 1, &cds, 0, NULL);
        vkCmdDispatch(cb, 8, 1, 1);
        submit(cb);
        int bad = 0;
        for (unsigned i = 0; i < 1024; i++) {
            unsigned g = i / 128, j = 127 - i % 128, src = g * 128 + j, want = src * 3 + 11 + g * 7;
            if (bp[i] != want) { if (bad < 4) fprintf(stderr, "vk compute: [%u] = %u, want %u\n", i, bp[i], want); bad++; }
        }
        printf("vk compute: %d of 1024 values wrong\n", bad);
    }
    return 0;
}
